			bool isStore = Opcode == ARM_STREXD || Opcode == ARM_STLEXD;
			unsigned Reg = MCOperand_getReg(MCInst_getOperand(MI, isStore ? 1 : 0));

			if (MCRegisterClass_contains(MRC, Reg)) {
			    MCInst NewMI;

			    MCInst_Init(&NewMI);
			    MCInst_setOpcode(&NewMI, Opcode);

			    if (isStore)
					MCInst_addOperand2(&NewMI, MCInst_getOperand(MI, 0));

			    MCOperand_CreateReg0(&NewMI, MCRegisterInfo_getMatchingSuperReg(MRI, Reg, ARM_gsub_0,
							MCRegisterInfo_getRegClass(MRI, ARM_GPRPairRegClassID)));

			    // Copy the rest operands into NewMI.
			    for(i = isStore ? 3 : 2; i < MCInst_getNumOperands(MI); ++i)
					MCInst_addOperand2(&NewMI, MCInst_getOperand(MI, i));

			    printInstruction(&NewMI, O);
			    return;
			}
			break;
		}

		case ARM_TSB:
		case ARM_t2TSB:
			SStream_concat0(O, "tsb\tcsync");
		int64_t Address, const void *Decoder)
{
	// Decode the memri field (imm, reg), which has the low 16-bits as the
	// displacement and the next 5 bits as the register #.

	uint64_t Base = Imm >> 16;
	uint64_t Disp = Imm & 0xFFFF;

	// assert(Base < 32 && "Invalid base register");
	if (Base >= 32)
		return MCDisassembler_Fail;

	switch (MCInst_getOpcode(Inst)) {
		default: break;
		case PPC_LBZU:
		case PPC_LHAU:
		case PPC_LHZU:
		case PPC_LWZU:
		case PPC_LFSU:
		case PPC_LFDU:
				 // Add the tied output operand.
				 MCOperand_CreateReg0(Inst, GP0Regs[Base]);
				 break;
		case PPC_STBU:
		case PPC_STHU:
		case PPC_STWU:
		case PPC_STFSU:
		case PPC_STFDU:
				 MCInst_insert0(Inst, 0, MCOperand_CreateReg1(Inst, GP0Regs[Base]));
				 break;
	}

	MCOperand_CreateImm0(Inst, SignExtend64(Disp, 16));
	MCOperand_CreateReg0(Inst, GP0Regs[Base]);

	return MCDisassembler_Success;
}

static DecodeStatus decodeMemRIXOperands(MCInst *Inst, uint64_t Imm,
		int64_t Address, const void *Decoder)
{
	// Decode the memrix field (imm, reg), which has the low 14-bits as the
	// displacement and the next 5 bits as the register #.

	uint64_t Base = Imm >> 14;
	uint64_t Disp = Imm & 0x3FFF;

	// assert(Base < 32 && "Invalid base register");
	if (Base >= 32)
		return MCDisassembler_Fail;

	if (MCInst_getOpcode(Inst) == PPC_LDU)
		// Add the tied output operand.
		MCOperand_CreateReg0(Inst, GP0Regs[Base]);
	else if (MCInst_getOpcode(Inst) == PPC_STDU)
		MCInst_insert0(Inst, 0, MCOperand_CreateReg1(Inst, GP0Regs[Base]));

	MCOperand_CreateImm0(Inst, SignExtend64(Disp << 2, 16));
	MCOperand_CreateReg0(Inst, GP0Regs[Base]);

	return MCDisassembler_Success;
}

static DecodeStatus decodeMemRIX16Operands(MCInst *Inst, uint64_t Imm,
		int64_t Address, const void *Decoder)
