# Define helpers to write/run fuzz_disasm locally, and test a simple x86 nop input.
from pathlib import Path
import subprocess, os, binascii, json, textwrap, time, random, itertools, struct
BIN = '/workspace/src-vul/capstonenext/build/fuzz_disasm'

def write_bytes(path, data):
    Path(path).write_bytes(data)
    return path

def run_local(data=None, path='/tmp/local_poc', timeout=5, extra_env=None, args=None):
    if data is not None:
        Path(path).write_bytes(data)
    env = os.environ.copy()
    env.setdefault('MSAN_OPTIONS','halt_on_error=1:exit_code=86:report_umrs=1:print_stacktrace=1:symbolize=1')
    if extra_env:
        env.update(extra_env)
    cmd = [BIN]
    if args:
        cmd += args
    else:
        cmd += [path]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout, env=env)
    return p.returncode, p.stdout.decode('latin1', 'replace'), p.stderr.decode('latin1', 'replace')

for data in [bytes([0,0x90]), bytes([1,0x90]), bytes([7,0,0,0,0])]:
    rc,out,err = run_local(data)
    print('data', data.hex(), 'rc', rc, 'out', out[:100], 'err', err[:300])

